const trigger = $items('Create Video Request')[0].json
const body = trigger.body || trigger
const toolText = String($items('Discover Tools')[0].json.stdout || '')

function pick(name, fallback) {
  const value = body[name]
  if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim()
  return fallback
}

function clean(value) {
  return String(value || '').replaceAll('\n', ' ').replaceAll('\r', ' ').replaceAll('"', '').trim()
}

function shellQuote(value) {
  return "'" + String(value || '').replaceAll("'", "'\"'\"'") + "'"
}

function tokens(text) {
  const separators = ' \n\r\t,|[]{}():"\''
  let current = ''
  const out = []
  for (const ch of String(text || '')) {
    if (separators.includes(ch)) {
      if (current) out.push(current)
      current = ''
    } else {
      current = current + ch
    }
  }
  if (current) out.push(current)
  return out
}

function chooseTool(text, preferred) {
  if (preferred) return preferred
  const words = tokens(text)
  let fallback = ''
  for (const word of words) {
    const lower = word.toLowerCase()
    if (!fallback && lower.includes('video')) fallback = word
    if ((lower.includes('image') && lower.includes('video')) || lower.includes('i2v')) return word
  }
  if (fallback) return fallback
  throw new Error('No compatible video tool was found in insmind-cli tool list. Add insmind_tool to the webhook body after checking discovery output.')
}

let duration = Number(pick('duration_seconds', pick('duration', '10')))
if (![5, 10, 15].includes(duration)) duration = 10

const productName = clean(pick('product_name', 'Fruit product'))
const goal = clean(pick('campaign_goal', 'Create a short social marketing video that turns the product into a memorable character moment.'))
const language = clean(pick('story_language', pick('language', 'English')))
const ratio = clean(pick('aspect_ratio', '9:16'))
const image = pick('product_image_path', pick('image_path', pick('product_image_url', pick('image_url', ''))))
if (!image) throw new Error('Provide product_image_path or product_image_url')

const selectedTool = chooseTool(toolText, clean(pick('insmind_tool', '')))
const beats = duration <= 5 ? 'setup and payoff' : duration <= 10 ? 'hook, complication, payoff' : 'hook, desire, reversal, payoff'
const prompt = [
  'Use the supplied product image as the identity reference for the same fruit or vegetable character throughout.',
  'Product or character: ' + productName + '.',
  'Marketing goal: ' + goal + '.',
  'Story shape: ' + beats + '.',
  'Preserve produce type, silhouette, face placement, texture, palette, outfit or packaging cues, and a signature gesture.',
  'Create a cinematic stylized 3D animated short with expressive acting and readable silhouettes.',
  'Sound language: ' + language + '.',
  'Format: ' + duration + ' seconds, ' + ratio + ' aspect ratio.',
  'Avoid identity drift, duplicate limbs, unreadable text, random logos, protected characters, and human faces behind fruit masks.'
].join(' ')

const submitCommand = 'insmind-cli tool call ' + shellQuote(selectedTool) + ' --prompt ' + shellQuote(prompt) + ' --image ' + shellQuote(image) + ' --async'

return [{
  json: {
    selected_tool: selectedTool,
    prompt: prompt,
    image: image,
    duration_seconds: duration,
    aspect_ratio: ratio,
    submit_command: submitCommand
  }
}]

