}
let resultUrl = ''
for (const word of tokens(text)) {
  const lower = word.toLowerCase()
  if ((lower.startsWith('http://') || lower.startsWith('https://')) && (lower.includes('video') || lower.includes('result') || lower.includes('download') || lower.includes('mp4') || lower.includes('mov') || lower.includes('webm'))) {
    resultUrl = word
    break
  }
}
const failed = text.toLowerCase().includes('failed') || text.toLowerCase().includes('error') || text.toLowerCase().includes('rejected')
return [{ json: { success: Boolean(resultUrl) && !failed, workflow_status: resultUrl ? 'completed' : failed ? 'failed' : 'pending', result_url: resultUrl, raw_task_output: text } }]
